        self.assertEqual(payload["request"], {"line_count": 2, "since": "5m", "search": "contact"})
        self.assertEqual(payload["logs"]["lines"], ["ok", "RESEND_API_KEY=[redacted]"])
        self.assertNotIn("secret-token", json.dumps(payload))

